#!/bin/sh
# Generated by sdk-kit 0.2.0 — do not edit; change sdk-kit and run "sdk-kit sync"
#
# wait-for-tcp.sh — wait until a TCP port accepts connections.
# POSIX sh; tries nc, bash /dev/tcp, python3 and curl in that order.
#
# usage: wait-for-tcp.sh [-t TIMEOUT_S] [-i INTERVAL_S] [-q] HOST:PORT
# exit: 0 ready, 1 timed out, 2 usage error or no usable client
set -eu

timeout=60
interval=1
quiet=0

say() {
	[ "$quiet" -eq 1 ] || printf 'wait-for-tcp: %s\n' "$*" >&2
}

usage() {
	printf 'usage: %s [-t TIMEOUT_S] [-i INTERVAL_S] [-q] HOST:PORT\n' "$0" >&2
	exit 2
}

is_uint() {
	case $1 in '' | *[!0-9]*) return 1 ;; esac
	return 0
}

while getopts "t:i:q" opt; do
	case $opt in
	t) timeout=$OPTARG ;;
	i) interval=$OPTARG ;;
	q) quiet=1 ;;
	*) usage ;;
	esac
done
shift $((OPTIND - 1))
[ $# -eq 1 ] || usage
is_uint "$timeout" || usage
is_uint "$interval" || usage
[ "$interval" -ge 1 ] || interval=1
host=${1%:*}
port=${1##*:}
[ -n "$host" ] && [ "$host" != "$1" ] || usage
is_uint "$port" || usage
# allow [::1]:8080
host=${host#[}
host=${host%]}

if command -v nc >/dev/null 2>&1; then
	client=nc
elif command -v bash >/dev/null 2>&1; then
	client=bash
elif command -v python3 >/dev/null 2>&1; then
	client=python3
elif command -v curl >/dev/null 2>&1; then
	client=curl
else
	say "no usable client (nc, bash, python3 or curl)"
	exit 2
fi

probe() {
	case $client in
	nc) nc -z -w 2 "$host" "$port" >/dev/null 2>&1 ;;
	bash) bash -c 'exec 3<>"/dev/tcp/$0/$1"' "$host" "$port" >/dev/null 2>&1 ;;
	python3) python3 -c 'import socket,sys; socket.create_connection((sys.argv[1], int(sys.argv[2])), 2).close()' "$host" "$port" >/dev/null 2>&1 ;;
	curl)
		# curl's telnet:// handler keeps an open connection until --max-time; a non-zero
		# connect time proves the port accepted the connection.
		connected=$(curl -s -o /dev/null -w '%{time_connect}' --max-time 2 "telnet://$host:$port" </dev/null 2>/dev/null) || true
		case $connected in *[1-9]*) return 0 ;; *) return 1 ;; esac
		;;
	esac
}

start=$(date +%s)
while :; do
	if probe; then
		say "$host:$port is open"
		exit 0
	fi
	now=$(date +%s)
	if [ $((now - start)) -ge "$timeout" ]; then
		say "timed out after ${timeout}s waiting for $host:$port"
		exit 1
	fi
	sleep "$interval"
done
